check("06 BOX audit", source.sql.includes("DRIVE_BOX_CREATED") && source.sql.includes("DRIVE_BOX_ITEM_ADDED") && source.sql.includes("DRIVE_BOX_ITEM_REMOVED"), "BOX változások projektauditba kerülnek.");
