check("158 Vizuális score reset életciklus", source.visualCompare.includes("setAutoCandidateVisualQuality({})") && source.visualCompare.includes("[fitWidth, pageNumber, rotation, zoom]") && source.visualCompare.includes("[autoAlignmentCandidateIndex]: null"), "Renderállapot-váltás vagy kézi referencia-pár csere után a vizuális score nem maradhat elavult.");
check("159 Vizuális score responsive UI", source.css.includes("Drive Visual Compare Visual Quality Score V1") && source.css.includes("visualCompareAutoCandidateQuality") && source.css.includes("@media (max-width: 760px)"), "A vizuális minőségjelzés a candidate preview responsive Drive UI-jába illeszkedik.");
check("160 Eltérési zóna adatmodell", source.visualCompare.includes("VisualDifferenceZone") && source.visualCompare.includes("mismatchPixels") && source.visualCompare.includes("inkPixels") && source.visualCompare.includes("zones: VisualDifferenceZone[]"), "A vizuális score külön, auditálható eltérési zónákat tart fenn.");
check("161 Lokális mismatch detektálás", source.visualCompare.includes("hasA && !rightDilated[index]") && source.visualCompare.includes("hasB && !leftDilated[index]") && source.visualCompare.includes("mismatchPixels += 1"), "A hőtérkép a kétirányú, tolerált vonaleltérést lokálisan is méri.");
check("162 Rácsalapú hőtérkép", source.visualCompare.includes("gridColumns = 8") && source.visualCompare.includes("gridRows = 5") && source.visualCompare.includes("zoneScore") && source.visualCompare.includes("zones.slice(0, 5)"), "A bitmap eltérés 8×5 rácson aggregálódik és a legerősebb öt zóna kerül előre.");
check("163 Feature-szegény zónák szűrése", source.visualCompare.includes("inkPixels < 5") && source.visualCompare.includes("zoneScore < 8"), "Üres vagy túl gyenge cella nem jelenik meg félrevezető eltérési zónaként.");
check("164 Zónák visszamappelése tervkoordinátára", source.visualCompare.includes("(zone.x - originX) / Math.max(0.0001, fitScale)") && source.visualCompare.includes("sourceWidth - x") && source.visualCompare.includes("sourceHeight - y"), "A thumbnail rácszónák visszaalakítása a renderelt terv koordinátarendszerére megtörténik.");
check("165 Thumbnail hőtérkép", source.visualCompare.includes("rawQuality?.zones.length") && source.visualCompare.includes("context.fillRect(zone.x, zone.y, zone.width, zone.height)") && source.visualCompare.includes("rgba(220,76,55"), "A candidate thumbnail a legerősebb eltérési cellákat vizuálisan is kiemeli.");
check("166 Hőtérkép kapcsoló", source.visualCompare.includes("differenceHeatmapEnabled") && source.visualCompare.includes("data-difference-heatmap-toggle") && source.visualCompare.includes("Hőtérkép be") && source.visualCompare.includes("Hőtérkép ki"), "Az aktív Auto Align javaslat hőtérképe külön be/ki kapcsolható.");
check("167 Fő terven eltérési overlay", source.visualCompare.includes("data-difference-zone-overlay") && source.visualCompare.includes("visualCompareDifferenceZoneOverlay") && source.css.includes("visualCompareDifferenceZoneOverlayActive"), "A kiválasztott hőtérkép zónák a nagy terven külön overlay-ként láthatók.");
check("168 Eltérési zóna fókusz", source.visualCompare.includes("focusDifferenceZone") && source.visualCompare.includes("stage.scrollTo") && source.visualCompare.includes("behavior: \"smooth\""), "Egy zóna kiválasztása a Compare munkaterületet az adott eltérés környezetére görgeti.");
check("169 Zónanagyító inspector", source.visualCompare.includes("DifferenceZoneInspector") && source.visualCompare.includes("data-difference-inspector") && source.visualCompare.includes("Eltérési zóna ${zoneIndex + 1} nagyított előnézete"), "A kiválasztott eltérési zóna külön nagyított A/B ellenőrző előnézetet kap.");
check("170 Inspector candidate transzformációval", source.visualCompare.includes("context.translate(candidate.offsetX, candidate.offsetY)") && source.visualCompare.includes("context.rotate(candidate.rotationDegrees") && source.visualCompare.includes("context.scale(candidateScale, candidateScale)"), "A zónanagyító ugyanazzal a similarity transzformációval mutatja a B tervet, mint az Auto Align jelölt.");
check("171 Hőtérkép nem alkalmaz igazítást", source.visualCompare.includes("function focusDifferenceZone") && !source.visualCompare.slice(source.visualCompare.indexOf("function focusDifferenceZone"), source.visualCompare.indexOf("function startAutoPairReplacement")).includes("setAlignmentOffsetX"), "A hőtérkép/zónafókusz nem módosítja a jóváhagyásra váró B-réteg transzformációt.");
check("172 Hőtérkép életciklus reset", source.visualCompare.includes("setDifferenceHeatmapEnabled(false)") && source.visualCompare.includes("setSelectedDifferenceZoneIndex(0)") && source.visualCompare.includes("setAutoCandidateVisualQuality({})"), "Új elemzés, renderállapot-váltás vagy elvetés után az eltérési hőtérkép nem marad elavult.");
check("173 Hőtérkép responsive UI", source.css.includes("Drive Visual Compare Difference Heatmap V1") && source.css.includes("visualCompareDifferenceZoneList") && source.css.includes("visualCompareDifferenceInspector") && source.css.includes("@media (max-width: 520px)"), "A zónalista és nagyító laptopon/keskeny nézetben is kontrolláltan tördelődik.");
check("174 Shared PDF vectorSegments adatmodell", source.pdfEngine.includes("SharedPdfVectorSegment") && source.pdfEngine.includes("vectorSegments: SharedPdfVectorSegment[]"), "A közös PDF elemző a kontúrok mellett normalizált vektorszegmenseket is visszaad.");
check("175 Nyitott/zárt vektorszegmens forrás", source.pdfEngine.includes('source: "openPath" | "closedPath"') && source.pdfEngine.includes('path.closed ? "closedPath" : "openPath"'), "A parser megőrzi, hogy a vonal nyitott vagy zárt path-ból származik.");
check("176 Vektorszegmens irányszög", source.pdfEngine.includes("angleDegrees") && source.pdfEngine.includes("vectorSegmentAngleDegrees"), "Minden szegmens 0–180° közötti irányjellemzőt kap.");
check("177 Vektorszegmens deduplikáció", source.pdfEngine.includes("deduplicateVectorSegments") && source.pdfEngine.includes("vectorSegmentSignature") && source.pdfEngine.includes("12000"), "A PDF operatorlistából duplikált vonalak kvantált végpont-aláírással kiszűrésre kerülnek.");
check("178 Közös analyzer publikálja a szegmenseket", source.pdfEngine.includes("vectorSegments: geometry.segments") && source.pdfEngine.includes("lineSegmentCount: geometry.segments.length"), "A SharedPdfPageAnalysis ugyanabból az engine-ből ad szegmenslistát és darabszámot.");
check("179 VECTOR_SEGMENTS Auto Align forrás", source.autoAlignment.includes('"VECTOR_SEGMENTS"') && source.visualCompare.includes('source === "VECTOR_SEGMENTS"') && source.visualCompare.includes("nyitott CAD/PDF vektorvonalak"), "A Drive külön Auto Align forrásként kezeli a nyitott műszaki vektorvonalakat.");
check("180 Open-path szegmens szűrés", source.autoAlignment.includes("usableOpenSegments") && source.autoAlignment.includes('segment.source === "openPath"') && source.autoAlignment.includes("segment.length >= 0.018"), "Az új matcher elsősorban a megfelelő hosszúságú nyitott vonalakat használja.");
check("181 Szegmens seed similarity", source.autoAlignment.includes("seedSegmentTransform") && source.autoAlignment.includes("signedUndirectedRotationDegrees") && source.autoAlignment.includes("left.length / Math.max"), "A RANSAC-szerű seed vonalpárból egységes skála/forgatás/eltolás hipotézis készül.");
check("182 Szegmens konzisztencia matching", source.autoAlignment.includes("matchOpenSegmentsUnderTransform") && source.autoAlignment.includes("positionError > 0.032") && source.autoAlignment.includes("angleError > 7.5") && source.autoAlignment.includes("lengthError > 0.12"), "A további vektorvonalak pozíció, irány és hossz szerint igazolják vagy elvetik a seed hipotézist.");
check("183 Kölcsönösen egyedi szegmens használat", source.autoAlignment.includes("usedLeft") && source.autoAlignment.includes("usedRight") && source.autoAlignment.includes("usedLeft.has") && source.autoAlignment.includes("usedRight.has"), "Egy vonal egy proposalban legfeljebb egy referenciapárhoz használható.");
check("184 Szegmens proposal minimum evidencia", source.autoAlignment.includes("pairs.length < 3") && source.autoAlignment.includes("spread < 0.14") && source.autoAlignment.includes("evidenceCount: best.pairs.length"), "Legalább három konzisztens egyezés és térbeli szórás szükséges a nyitottvonal-javaslathoz.");
check("185 Szegmens proposal emberi review-ba kerül", source.autoAlignment.includes("const segments = openSegmentProposal") && source.autoAlignment.includes("candidates.push(segments)") && source.visualCompare.includes("Automatikus illesztési javaslat") && source.visualCompare.includes("Alkalmazás"), "A nyitottvonal-eredmény ugyanabba a meglévő emberi jóváhagyási workflow-ba kerül.");
check("186 Geometriai metszések nyitott szegmensekből", source.autoAlignment.includes("analysis.vectorSegments?.length") && source.autoAlignment.includes("segment.pathIndex") && source.autoAlignment.includes("buildIntersectionNodes"), "A geometriai csomópont-felismerés már a nyitott szegmensek metszéseit is felhasználhatja.");
check("187 Auto Align diagnosztika vektorvonal darabszám", source.visualCompare.includes("nyitott vektorvonal") && source.visualCompare.includes("leftAnalysis.vectorSegments?.filter") && source.visualCompare.includes("rightAnalysis.vectorSegments?.filter"), "Sikertelen automatikus illesztésnél a diagnosztika megmutatja a felismert nyitott vonalak számát.");
check("188 Shared parser megmarad egyetlen operator parsernek", source.pdfEngine.includes("getOperatorList") && !source.autoAlignment.includes("getOperatorList") && !source.autoAlignment.includes("constructPath"), "A Drive továbbra sem duplikál PDF operator parsert; a közös engine vectorSegments adatára épül.");
check("189 Kis vektoros PDF helyes contentKind", source.pdfEngine.includes("vectorPathCount > 0 || geometry.segments.length > 0") && !source.pdfEngine.includes("geometry.segments.length >= 12"), "Már néhány valódi PDF vector path/szegmens esetén sem sorolódik tévesen raster kategóriába a tisztán vektoros tervlap.");

const failed = checks.filter((item) => !item.ok);
for (const item of checks) console.log(`${item.ok ? "PASS" : "FAIL"} ${item.name} — ${item.detail}`);
console.log(`\nÖsszesen: ${checks.length} acceptance/contract ellenőrzés, ${failed.length} hiba.`);
if (failed.length) process.exit(1);
